package io.github.foodjournal.messaging;
import io.github.foodjournal.domain.*; import io.github.foodjournal.repository.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class MessagingDailyStatusService { private final UserSettingsRepository settings; private final FoodEntryRepository entries; private final MessagingDailyStatusRepository statuses; public MessagingDailyStatusService(UserSettingsRepository settings,FoodEntryRepository entries,MessagingDailyStatusRepository statuses){this.settings=settings;this.entries=entries;this.statuses=statuses;} @Transactional public void refresh(FoodUser user,String provider,String conversation){UserSettings s=settings.findById(user.getId()).orElseThrow();ZoneId z=ZoneId.of(s.getTimezone());List<FoodEntry> rows=entries.findByUserAndEatenAtBetweenOrderByEatenAtAsc(user,LocalDate.now(z).atStartOfDay(z).toInstant(),LocalDate.now(z).plusDays(1).atStartOfDay(z).toInstant());int total=rows.stream().map(FoodEntry::getCalories).filter(Objects::nonNull).mapToInt(Integer::intValue).sum();String text="Today: "+rows.size()+" entries, "+total+" kcal logged."+(s.getCalorieTarget()==null?"":" Target: "+s.getCalorieTarget()+" kcal.");statuses.findByUserAndProviderAndConversationId(user,provider,conversation).ifPresentOrElse(row->row.request(text),()->statuses.save(new MessagingDailyStatus(user,provider,conversation,text)));} @Transactional public MessagingDailyStatus claim(){return statuses.lockDirty().stream().findFirst().orElse(null);} }
